CREATE FUNCTION public.workspace_stats() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('suppliers',(SELECT count(*) FROM public.suppliers),'products',(SELECT count(*) FROM public.products),'visits',(SELECT count(*) FROM public.sourcing_visits),'markets',(SELECT count(DISTINCT market) FROM public.suppliers),'photos',(SELECT count(*) FROM public.supplier_photos)+(SELECT count(*) FROM public.product_photos)+(SELECT coalesce(sum(cardinality(photos)),0) FROM public.product_colors),'drafts',(SELECT count(*) FROM public.suppliers WHERE status='draft')+(SELECT count(*) FROM public.products WHERE status='draft'),'reports',(SELECT count(*) FROM public.sourcing_visits WHERE status='submitted'),'agents',(SELECT count(*) FROM public.user_roles WHERE role='agent')) $$;
REVOKE EXECUTE ON FUNCTION public.workspace_stats() FROM public,anon; GRANT EXECUTE ON FUNCTION public.workspace_stats() TO authenticated;
CREATE FUNCTION public.check_photo_paths(paths text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p text; BEGIN IF cardinality(paths)<1 THEN RAISE EXCEPTION 'At least one photograph is required'; END IF; FOREACH p IN ARRAY paths LOOP IF p NOT LIKE auth.uid()::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='sourcing-photos' AND name=p) THEN RAISE EXCEPTION 'Upload your photograph before submitting'; END IF; END LOOP; END $$;
REVOKE EXECUTE ON FUNCTION public.check_photo_paths(text[]) FROM public,anon,authenticated;
CREATE FUNCTION public.submit_supplier(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid:=(payload->>'id')::uuid; p text; paths text[]; BEGIN IF NOT public.can_source() THEN RAISE EXCEPTION 'Not authorized'; END IF; IF EXISTS(SELECT 1 FROM public.suppliers WHERE id=sid AND created_by=auth.uid()) THEN RETURN sid; END IF; SELECT array_agg(value) INTO paths FROM jsonb_array_elements_text(payload->'photos'); PERFORM public.check_photo_paths(coalesce(paths,'{}')); IF payload->'gps'->>'latitude' IS NULL OR payload->'gps'->>'longitude' IS NULL THEN RAISE EXCEPTION 'GPS location is required'; END IF;
INSERT INTO public.suppliers(id,created_by,name,contact_person,mobile,shop_number,market,address,visit_date,type,relationship,notes,details,latitude,longitude,status) VALUES(sid,auth.uid(),payload->>'name',payload->>'contact_person',payload->>'mobile',payload->>'shop_number',payload->>'market',payload->>'address',(payload->>'visit_date')::date,payload->>'type',payload->>'relationship',payload->>'notes',payload->'details',(payload->'gps'->>'latitude')::float8,(payload->'gps'->>'longitude')::float8,payload->>'status');
FOREACH p IN ARRAY paths LOOP INSERT INTO public.supplier_photos(supplier_id,path,created_by) VALUES(sid,p,auth.uid()); END LOOP;
IF payload->>'visit_id' IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM public.sourcing_visits WHERE id=(payload->>'visit_id')::uuid AND created_by=auth.uid() AND status='active') THEN RAISE EXCEPTION 'Choose your active visit'; END IF; INSERT INTO public.visit_suppliers(visit_id,supplier_id) VALUES((payload->>'visit_id')::uuid,sid) ON CONFLICT DO NOTHING; END IF;
INSERT INTO public.gps_records(created_by,supplier_id,visit_id,kind,latitude,longitude,accuracy) VALUES(auth.uid(),sid,(payload->>'visit_id')::uuid,'Supplier check-in',(payload->'gps'->>'latitude')::float8,(payload->'gps'->>'longitude')::float8,(payload->'gps'->>'accuracy')::float8); RETURN sid; END $$;
CREATE FUNCTION public.submit_product(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE pid uuid:=(payload->>'id')::uuid; item jsonb; paths text[]; p text; q integer; BEGIN IF NOT public.can_source() THEN RAISE EXCEPTION 'Not authorized'; END IF; IF EXISTS(SELECT 1 FROM public.products WHERE id=pid AND created_by=auth.uid()) THEN RETURN pid; END IF; SELECT array_agg(value) INTO paths FROM jsonb_array_elements_text(payload->'photos'); PERFORM public.check_photo_paths(coalesce(paths,'{}')); IF payload->'gps'->>'latitude' IS NULL OR payload->'gps'->>'longitude' IS NULL THEN RAISE EXCEPTION 'GPS location is required'; END IF;
FOREACH q IN ARRAY ARRAY[10,100,500] LOOP IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(payload->'tiers') t WHERE (t->>'quantity')::integer=q) THEN RAISE EXCEPTION '10, 100, and 500 piece quotations are required'; END IF; END LOOP;
IF payload->>'color_mode'='Yes' AND jsonb_array_length(payload->'colors')=0 THEN RAISE EXCEPTION 'Color photographs are required'; END IF; IF payload->>'size_mode'='Yes' AND jsonb_array_length(payload->'sizes')=0 THEN RAISE EXCEPTION 'Sizes are required'; END IF;
IF payload->>'visit_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sourcing_visits WHERE id=(payload->>'visit_id')::uuid AND created_by=auth.uid() AND status='active') THEN RAISE EXCEPTION 'Choose your active visit'; END IF;
INSERT INTO public.products(id,supplier_id,category_id,visit_id,created_by,name,description,quality,material,moq,stock,color_mode,size_mode,details,status,latitude,longitude) VALUES(pid,(payload->>'supplier_id')::uuid,(payload->>'category_id')::uuid,(payload->>'visit_id')::uuid,auth.uid(),payload->>'name',payload->>'description',payload->>'quality',payload->>'material',(payload->>'moq')::integer,(payload->>'stock')::integer,payload->>'color_mode',payload->>'size_mode',payload->'details',payload->>'status',(payload->'gps'->>'latitude')::float8,(payload->'gps'->>'longitude')::float8);
FOREACH p IN ARRAY paths LOOP INSERT INTO public.product_photos(product_id,path,created_by) VALUES(pid,p,auth.uid()); END LOOP;
FOR item IN SELECT value FROM jsonb_array_elements(payload->'tiers') LOOP INSERT INTO public.product_price_tiers(product_id,quantity,unit_price,unavailable) VALUES(pid,(item->>'quantity')::integer,(item->>'unit_price')::numeric,(item->>'unavailable')::boolean); END LOOP;
IF payload->>'color_mode'='Yes' THEN FOR item IN SELECT value FROM jsonb_array_elements(payload->'colors') LOOP SELECT array_agg(value) INTO paths FROM jsonb_array_elements_text(item->'photos'); PERFORM public.check_photo_paths(coalesce(paths,'{}')); INSERT INTO public.product_colors(product_id,name,code,photos,availability,remarks) VALUES(pid,item->>'name',item->>'code',paths,item->>'availability',item->>'remarks'); END LOOP; END IF;
IF payload->>'size_mode'='Yes' THEN FOR item IN SELECT value FROM jsonb_array_elements(payload->'sizes') LOOP INSERT INTO public.product_sizes(product_id,name,availability,remarks) VALUES(pid,item->>'name',item->>'availability',item->>'remarks'); END LOOP; END IF;
IF payload->>'visit_id' IS NOT NULL THEN INSERT INTO public.visit_suppliers(visit_id,supplier_id) VALUES((payload->>'visit_id')::uuid,(payload->>'supplier_id')::uuid) ON CONFLICT DO NOTHING; END IF;
INSERT INTO public.gps_records(created_by,product_id,supplier_id,visit_id,kind,latitude,longitude,accuracy) VALUES(auth.uid(),pid,(payload->>'supplier_id')::uuid,(payload->>'visit_id')::uuid,'Product submitted',(payload->'gps'->>'latitude')::float8,(payload->'gps'->>'longitude')::float8,(payload->'gps'->>'accuracy')::float8); RETURN pid; END $$;
CREATE FUNCTION public.record_visit(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE vid uuid:=(payload->>'id')::uuid; BEGIN IF NOT public.can_source() THEN RAISE EXCEPTION 'Not authorized'; END IF; IF payload->'gps'->>'latitude' IS NULL OR payload->'gps'->>'longitude' IS NULL THEN RAISE EXCEPTION 'GPS location is required'; END IF;
IF payload->>'action'='start' THEN INSERT INTO public.sourcing_visits(id,created_by,market,notes) VALUES(vid,auth.uid(),payload->>'market',payload->>'notes'); ELSE UPDATE public.sourcing_visits SET status='submitted',ended_at=now(),notes=payload->>'notes' WHERE id=vid AND created_by=auth.uid() AND status='active'; IF NOT FOUND THEN RAISE EXCEPTION 'Visit is not active or is not yours'; END IF; END IF;
INSERT INTO public.gps_records(created_by,visit_id,kind,latitude,longitude,accuracy) VALUES(auth.uid(),vid,CASE WHEN payload->>'action'='start' THEN 'Visit started' ELSE 'Visit completed' END,(payload->'gps'->>'latitude')::float8,(payload->'gps'->>'longitude')::float8,(payload->'gps'->>'accuracy')::float8); RETURN vid; END $$;
REVOKE EXECUTE ON FUNCTION public.submit_supplier(jsonb),public.submit_product(jsonb),public.record_visit(jsonb) FROM public,anon; GRANT EXECUTE ON FUNCTION public.submit_supplier(jsonb),public.submit_product(jsonb),public.record_visit(jsonb) TO authenticated;
REVOKE INSERT ON public.suppliers,public.products,public.sourcing_visits,public.supplier_photos,public.product_photos,public.product_colors,public.product_sizes,public.product_variations,public.product_price_tiers,public.visit_suppliers,public.gps_records FROM authenticated;
CREATE FUNCTION public.accept_team_invitation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL THEN UPDATE public.user_invitations SET status='accepted' WHERE invited_user_id=NEW.id AND status='pending'; END IF; RETURN NEW; END $$;
CREATE TRIGGER accept_team_invitation AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.accept_team_invitation();
REVOKE EXECUTE ON FUNCTION public.create_profile(),public.audit_record(),public.accept_team_invitation() FROM public,anon,authenticated;